from jinja2 import Environment, FileSystemLoader, StrictUndefined

env = Environment(loader=FileSystemLoader("prompts"),
                  undefined=StrictUndefined,       # missing variable -> error
                  autoescape=False)

def render(ticket_text: str, tier: str) -> str:
    return env.get_template("support.j2").render(ticket=ticket_text, tier=tier)

